#!/usr/bin/env node
/**
 * Exports the canonical SQL schema (packages/core/src/storage/schema.ts) to
 * packages/core/sql/schema.sql so Cloudflare D1 / external tooling can apply it.
 */
import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { SCHEMA_STATEMENTS } from '../packages/core/src/storage/schema.ts';

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const target = join(root, 'packages/core/sql/schema.sql');

const header = [
  '-- BotForge schema (generated by scripts/export-schema.mjs)',
  '-- Compatible with PostgreSQL, SQLite and Cloudflare D1.',
  ''
].join('\n');

await mkdir(dirname(target), { recursive: true });
await writeFile(target, `${header}${SCHEMA_STATEMENTS.join(';\n\n')};\n`, 'utf8');
console.log(`schema exported: ${SCHEMA_STATEMENTS.length} statements → packages/core/sql/schema.sql`);
